package com.adent.shared.api;
import com.adent.shared.security.CurrentUser; import com.adent.staff.domain.Staff; import com.adent.staff.repository.StaffRepository; import com.adent.structure.domain.Room; import com.adent.structure.repository.RoomRepository; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/directory") @PreAuthorize("hasAnyRole('OWNER','RECEPTION','DENTIST','DENTAL_ASSISTANT')") public class DirectoryController {private final CurrentUser current;private final StaffRepository staff;private final RoomRepository rooms;public DirectoryController(CurrentUser c,StaffRepository s,RoomRepository r){current=c;staff=s;rooms=r;}@GetMapping("/staff") public List<Staff> staff(){return staff.findByTenantIdOrderByLastNamesAscFirstNamesAsc(current.tenantId()).stream().filter(Staff::isActive).toList();}@GetMapping("/rooms") public List<Room> rooms(){return rooms.findByTenantIdOrderByName(current.tenantId());}}
